    {
        "id": '2.M2.2',
        "pre_check": "KUBECONFIG=~/.kube/config kubectl exec -n aml-lab deploy/wazuh-master -c wazuh-manager -- grep -q '11111111-2222-3333-4444-555555555555' /var/ossec/etc/ossec.conf 2>/dev/null && KUBECONFIG=~/.kube/config kubectl exec -n aml-lab deploy/wazuh-master -c wazuh-manager -- test -f /var/ossec/integrations/custom-webhook 2>/dev/null",
        "pre_check_label": 'Wazuh custom-webhook integration and integration file configured in running container',
        "mode": 'remote',
        "title": 'M2.2 — Wazuh to Shuffle Webhook Integration',
        "desc": 'Configure custom-webhook integration in Wazuh master ossec.conf and restart master service.',
        "cmds": [{'label': 'Upload and run integration patch script', 'mode': 'remote_upload', 'script': '#!/bin/bash\nset -e\n\ncat << \'EOF\' > /tmp/wazuh_patch.py\nimport os\n\n# 1. Patch configmap\nconfig_path = \'/opt/aml-siem/k8s/base/wazuh-manager/wazuh-master-config.yaml\'\nif os.path.exists(config_path):\n    with open(config_path) as f:\n        content = f.read()\n    \n    if \'wazuh_alert_webhook_trigger\' in content:\n        content = content.replace(\'wazuh_alert_webhook_trigger\', \'11111111-2222-3333-4444-555555555555\')\n        \n    if \'custom-webhook\' not in content:\n        integration = \'\'\'      <integration>\n        <name>custom-webhook</name>\n        <hook_url>https://shuffle.aml-lab.infosecfoster.com/api/v1/hooks/11111111-2222-3333-4444-555555555555</hook_url>\n        <level>10</level>\n        <alert_format>json</alert_format>\n      </integration>\n\'\'\'\n        content = content.replace(\'    </ossec_config>\', integration + \'    </ossec_config>\')\n        \n    # Also fix old script if it exists (no SSL skip)\n    if \'custom-webhook:\' not in content or \'ssl.create_default_context\' not in content:\n        # Remove old entry if present\n        if \'custom-webhook:\' in content:\n            import re\n            content = re.sub(\'  custom-webhook: [|].*?(?=  \\w)\', \'\', content, flags=re.DOTALL)\n        script_body = \'\'\'  custom-webhook: |\n    #!/usr/bin/env python3\n    import sys, json, urllib.request, ssl, subprocess, socket\n    alert_file = sys.argv[1]\n    hook_url = sys.argv[3]\n    with open(alert_file, \'r\') as f:\n        alert_data = json.load(f)\n    # Resolve internal shuffle-backend ClusterIP via DNS\n    try:\n        svc_ip = socket.gethostbyname(\'shuffle-backend.aml-lab.svc.cluster.local\')\n        internal_url = f\'http://{svc_ip}:5001\' + hook_url[hook_url.index(\'/api/v1/hooks\'):]\n    except Exception:\n        internal_url = hook_url\n    ctx = ssl.create_default_context()\n    ctx.check_hostname = False\n    ctx.verify_mode = ssl.CERT_NONE\n    for url in [internal_url, hook_url]:\n        try:\n            req = urllib.request.Request(url, data=json.dumps(alert_data).encode(), headers={\'Content-Type\': \'application/json\'})\n            opener = urllib.request.build_opener(urllib.request.HTTPSHandler(context=ctx))\n            opener.open(req, timeout=10).read()\n            break\n        except Exception:\n            pass\n\'\'\'\n        content = content.replace(\'  local_rules.xml: |\', script_body + \'  local_rules.xml: |\')\n        \n    with open(config_path, \'w\') as f:\n        f.write(content)\n    print("CONFIG_PATCHED")\n\n# 2. Patch deployment\ndeploy_path = \'/opt/aml-siem/k8s/base/wazuh-manager/wazuh-master-deploy.yaml\'\nif os.path.exists(deploy_path):\n    with open(deploy_path) as f:\n        content = f.read()\n        \n    if \'custom-webhook\' not in content:\n        target_mount = \'        - name: config-volume\\n          mountPath: /var/ossec/integrations/custom-webhook\\n          subPath: custom-webhook\'\n        content = content.replace(\'        - name: shared-logs\', target_mount + \'\\n        - name: shared-logs\')\n        \n        old_volume = \'\'\'      - name: config-volume\n        configMap:\n          name: wazuh-master-config\'\'\'\n          \n        new_volume = \'\'\'      - name: config-volume\n        configMap:\n          name: wazuh-master-config\n          items:\n          - key: ossec.conf\n            path: ossec.conf\n          - key: local_decoder.xml\n            path: local_decoder.xml\n          - key: local_rules.xml\n            path: local_rules.xml\n          - key: filebeat.yml\n            path: filebeat.yml\n          - key: custom-webhook\n            path: custom-webhook\n            mode: 0755\'\'\'\n        content = content.replace(old_volume, new_volume)\n        with open(deploy_path, \'w\') as f:\n            f.write(content)\n        print("DEPLOY_PATCHED")\n    else:\n        print("DEPLOY_ALREADY_PATCHED")\nEOF\n\npython3 /tmp/wazuh_patch.py || true\nrm -f /tmp/wazuh_patch.py\n\n# Bootstrap Shuffle: create admin user and register webhook hook in OpenSearch\nSHUFFLE_SVC_IP=$(KUBECONFIG=~/.kube/config kubectl get svc shuffle-backend -n aml-lab -o jsonpath=\'{.spec.clusterIP}\' 2>/dev/null || echo \'\')\nOS_IP=$(KUBECONFIG=~/.kube/config kubectl get svc -n aml-lab opensearch -o jsonpath=\'{.spec.clusterIP}\' 2>/dev/null || echo \'\')\n\nif [ -n "$SHUFFLE_SVC_IP" ] && [ -n "$OS_IP" ]; then\n  # Create admin user (idempotent) - ignore output\n  curl -sk -X POST http://${SHUFFLE_SVC_IP}:5001/api/v1/users/register -H \'Content-Type: application/json\' -d \'{"username": "admin", "password": "Admin1234!", "email": "admin@infosecfoster.com"}\' >/dev/null 2>&1 || true\n  \n  # Login to get session_token cookie\n  APIKEY=$(curl -sk -X POST http://${SHUFFLE_SVC_IP}:5001/api/v1/users/login -H \'Content-Type: application/json\' -d \'{"username": "admin", "password": "Admin1234!"}\' 2>/dev/null | python3 -c \'import sys,json; d=json.load(sys.stdin); print(d.get("cookies",[{}])[0].get("value",""))\' 2>/dev/null || true)\n\n  # Get or create workflow\n  WORKFLOW_ID=$(curl -sk -b "session_token=${APIKEY}" http://${SHUFFLE_SVC_IP}:5001/api/v1/workflows 2>/dev/null | python3 -c \'import sys,json; wfs=json.load(sys.stdin); print(wfs[0]["id"] if isinstance(wfs,list) and wfs else "")\' 2>/dev/null || true)\n  if [ -z "$WORKFLOW_ID" ]; then\n    WORKFLOW_ID=$(curl -sk -X POST http://${SHUFFLE_SVC_IP}:5001/api/v1/workflows -b "session_token=${APIKEY}" -H \'Content-Type: application/json\' -d \'{"name":"Wazuh Alert Handler","description":"Receives Wazuh alerts via webhook","triggers":[{"id":"af2094c6-9d64-4cd1-b28c-881b9f4de58c","name":"Wazuh Webhook","trigger_type":"WEBHOOK","status":"running","app_name":"Webhook","app_version":"1.0.0"}],"actions":[]}\' 2>/dev/null | python3 -c \'import sys,json; print(json.load(sys.stdin).get("id",""))\' 2>/dev/null || true)\n  fi\n\n  TRIGGER_ID=\'af2094c6-9d64-4cd1-b28c-881b9f4de58c\'\n  URL_HOOK_SEGMENT="shuffle-${TRIGGER_ID}"  # 44 chars: Shuffle\'s required URL segment length\n  ORG_ID=$(curl -sk "http://${OS_IP}:9200/organizations/_search" 2>/dev/null | python3 -c \'import sys,json; d=json.load(sys.stdin); hits=d.get("hits",{}).get("hits",[]); print(hits[0]["_id"] if hits else "")\' 2>/dev/null || true)\n\n  # Recreate hooks index with id as keyword (Shuffle\'s GetHook uses term query on id)\n  curl -sk -X DELETE "http://${OS_IP}:9200/hooks" >/dev/null 2>&1 || true\n  curl -sk -X PUT "http://${OS_IP}:9200/hooks" -H \'Content-Type: application/json\' -d \'{"mappings":{"properties":{"id":{"type":"keyword"},"start":{"type":"keyword"},"status":{"type":"keyword"},"type":{"type":"keyword"},"owner":{"type":"keyword"},"org_id":{"type":"keyword"},"environment":{"type":"keyword"},"running":{"type":"boolean"},"auth":{"type":"keyword"},"workflows":{"type":"keyword"}}}}\' >/dev/null 2>&1 || true\n\n  # Upsert hook document with correct field structure\n  if [ -n "$WORKFLOW_ID" ]; then\n    curl -sk -X PUT "http://${OS_IP}:9200/hooks/_doc/${TRIGGER_ID}" -H \'Content-Type: application/json\' -d "{"id":"${TRIGGER_ID}","start":"${TRIGGER_ID}","info":{"name":"Wazuh Alert Webhook","description":""},"actions":[],"type":"webhook","owner":"","status":"running","workflows":["${WORKFLOW_ID}"],"running":true,"org_id":"${ORG_ID}","environment":"Shuffle","auth":""}" >/dev/null 2>&1 || true\n    curl -sk -X POST "http://${OS_IP}:9200/hooks/_refresh" >/dev/null 2>&1 || true\n\n    # Patch the hook_url in the running container\'s ossec.conf to use the 44-char URL segment\n    KUBECONFIG=~/.kube/config kubectl exec -n aml-lab deploy/wazuh-master -c wazuh-manager -- sed -i "s|/api/v1/hooks/.*</hook_url>|/api/v1/hooks/${URL_HOOK_SEGMENT}</hook_url>|g" /var/ossec/etc/ossec.conf 2>/dev/null || true\n    # Reload wazuh-integratord to pick up the updated ossec.conf\n    KUBECONFIG=~/.kube/config kubectl exec -n aml-lab deploy/wazuh-master -c wazuh-manager -- kill -HUP $(pgrep wazuh-integratord) 2>/dev/null || true\n    echo "SHUFFLE_HOOK_REGISTERED"\n  fi\nfi\n', 'remote_path': '/tmp/aml_wazuh_webhook_patch.py'}, {'label': 'Apply updated ConfigMap and Deployment to cluster', 'cmd': 'KUBECONFIG=~/.kube/config kubectl apply -f /opt/aml-siem/k8s/base/wazuh-manager/wazuh-master-config.yaml && KUBECONFIG=~/.kube/config kubectl apply -f /opt/aml-siem/k8s/base/wazuh-manager/wazuh-master-deploy.yaml'}, {'label': 'Restart Wazuh master deployment', 'cmd': 'KUBECONFIG=~/.kube/config kubectl rollout restart deployment wazuh-master -n aml-lab'}],
    },
